package in.tallybridge.app;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.text.NumberFormat;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

/** Fast native order notebook backed by the user's Windows TallyBridge PC. */
public final class OrdersActivity extends Activity {
 static final String ACTION_NEW="in.tallybridge.app.ORDER_NEW";
 private final ExecutorService work=Executors.newSingleThreadExecutor();
 private final Handler main=new Handler(Looper.getMainLooper());
 private CryptoStore store; private BridgeApi api;
 private LinearLayout root,body; private ProgressBar progress;
 private JSONObject boot=new JSONObject(),orderData=new JSONObject(),editing;
 private JSONArray companies=new JSONArray(),parties=new JSONArray(),stock=new JSONArray();
 private final Map<String,String> unitByItem=new HashMap<>();
 private final List<ItemRow> itemRows=new ArrayList<>();
 private JSONObject buyerDetails=new JSONObject(); private String buyerDetailsFor="";
 private boolean dispatchedTab=false,destroyed=false,mastersLoading=false;
 private int NAVY=0xff102d44,TEAL=0xff176b5b,MUTED=0xff596c79,BG=0xfff5f7fa,SURFACE=Color.WHITE,BORDER=0xffe4eaef,TINT=0xffe5f2ee;
 private final NumberFormat currency=NumberFormat.getCurrencyInstance(new Locale("en","IN"));

 static final class ItemRow {
  final LinearLayout box; final AutoCompleteTextView item; final EditText qty,rate; final TextView unit;
  ItemRow(LinearLayout b,AutoCompleteTextView i,EditText q,EditText r,TextView u){box=b;item=i;qty=q;rate=r;unit=u;}
 }

 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);currency.setCurrency(Currency.getInstance("INR"));try{store=new CryptoStore(this);api=new BridgeApi(store);}catch(Exception e){fatal(e);return;}if(store.get("base").isEmpty()||store.get("device").isEmpty()){needsMain("Connect and approve this phone in TallyBridge first.");return;}if(ACTION_NEW.equals(getIntent().getAction()))openForm(null);else showOrders();}
 @Override protected void onDestroy(){destroyed=true;work.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
 private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),BORDER);return d;}
 private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private TextView txt(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(4),0,dp(4));v.setLineSpacing(dp(2),1f);return v;}
 private void gap(LinearLayout l,int h){l.addView(new View(this),new LinearLayout.LayoutParams(1,dp(h)));}
 private Button btn(String s,View.OnClickListener c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(TEAL);b.setBackground(shape(SURFACE,13));b.setMinHeight(dp(50));b.setOnClickListener(c);return b;}
 private Button primary(String s,View.OnClickListener c){Button b=btn(s,c);b.setTextColor(Color.WHITE);b.setBackground(shape(TEAL,13));return b;}
 private EditText input(String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(16);e.setTextColor(NAVY);e.setHintTextColor(MUTED);e.setInputType(type);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(shape(SURFACE,12));e.setMinHeight(dp(52));return e;}
 private AutoCompleteTextView auto(String hint){AutoCompleteTextView a=new AutoCompleteTextView(this);a.setHint(hint);a.setTextSize(16);a.setTextColor(NAVY);a.setHintTextColor(MUTED);a.setPadding(dp(14),dp(12),dp(14),dp(12));a.setBackground(shape(SURFACE,12));a.setThreshold(1);a.setSingleLine(true);return a;}
 private LinearLayout.LayoutParams full(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,0);return p;}
 private void fatal(Exception e){TextView v=txt("Orders could not start.\n"+e.getMessage(),16,NAVY);v.setPadding(dp(24),dp(60),dp(24),dp(24));setContentView(v);}
 private void needsMain(String message){LinearLayout p=col();p.setPadding(dp(24),dp(60),dp(24),dp(24));p.addView(txt("TallyBridge Orders",28,NAVY));p.addView(txt(message,16,MUTED),full(16));p.addView(primary("Open TallyBridge",v->startActivity(new Intent(this,MainActivity.class))),full(24));setContentView(p);}
 private void frame(String title,String subtitle){root=col();root.setBackgroundColor(BG);root.setPadding(dp(18),dp(18),dp(18),dp(18));LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);LinearLayout titles=col();TextView t=txt(title,26,NAVY);t.setTypeface(Typeface.DEFAULT_BOLD);titles.addView(t);titles.addView(txt(subtitle,13,MUTED));h.addView(titles,new LinearLayout.LayoutParams(0,-2,1));Button close=btn("Back",v->finish());LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(84),-2);h.addView(close,cp);root.addView(h);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setVisibility(View.GONE);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(TEAL));root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));ScrollView scroll=new ScrollView(this);body=col();body.setPadding(0,dp(14),0,dp(26));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void busy(boolean yes){if(progress!=null)progress.setVisibility(yes?View.VISIBLE:View.GONE);}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void fail(Exception e){String m=e.getMessage()==null?"Could not reach your TallyBridge PC":e.getMessage();if(m.toLowerCase(Locale.ROOT).contains("sign")||m.contains("401")||m.contains("403")){needsMain("Open TallyBridge once to sign in/unlock, then return to Orders.\n\n"+m);}else toast(m);}

 private void call(String path,String method,String payload,java.util.function.Consumer<JSONObject> ok){busy(true);work.execute(()->{try{JSONObject x=api.call(path,method,payload==null?"":payload);main.post(()->{if(destroyed)return;busy(false);ok.accept(x);});}catch(Exception e){main.post(()->{if(!destroyed){busy(false);fail(e);}});}});}
 private void get(String path,java.util.function.Consumer<JSONObject> ok){call(path,"GET","",ok);}

 private void loadBootstrap(Runnable next){get("/api/v1/mobile/bootstrap",x->{boot=x;companies=x.optJSONArray("companies");if(companies==null)companies=new JSONArray();next.run();});}
 private List<String> companyNames(){List<String> out=new ArrayList<>();for(int i=0;i<companies.length();i++){JSONObject x=companies.optJSONObject(i);String n=x==null?companies.optString(i):x.optString("name");if(!n.isEmpty())out.add(n);}return out;}

 private void showOrders(){frame("Orders","Take an order during a call, share pending details, then mark it dispatched.");Button add=primary("+ Add order",v->openForm(null));body.addView(add);LinearLayout tabs=new LinearLayout(this);tabs.setPadding(0,dp(12),0,dp(8));Button pending=btn("Pending",v->{dispatchedTab=false;paintOrders();}),dispatched=btn("Dispatched",v->{dispatchedTab=true;paintOrders();});tabs.addView(pending,new LinearLayout.LayoutParams(0,-2,1));tabs.addView(dispatched,new LinearLayout.LayoutParams(0,-2,1));body.addView(tabs);TextView note=txt("Dispatched orders are view-only and are permanently removed 7 days after dispatch.",12,MUTED);body.addView(note);body.addView(txt("Loading orders…",15,MUTED),full(16));loadOrders();}
 private void loadOrders(){get("/api/v1/mobile/orders",x->{orderData=x;OrdersWidget.refreshAll(this);paintOrders();});}
 private void paintOrders(){if(body==null)return;while(body.getChildCount()>4)body.removeViewAt(4);int count=dispatchedTab?orderData.optInt("dispatchedCount"):orderData.optInt("pendingCount");TextView head=txt((dispatchedTab?"Dispatched":"Pending")+" • "+count,20,NAVY);head.setTypeface(Typeface.DEFAULT_BOLD);body.addView(head,full(10));JSONArray a=orderData.optJSONArray(dispatchedTab?"dispatched":"pending");if(a==null||a.length()==0){body.addView(txt(dispatchedTab?"No dispatched orders from the last 7 days.":"No pending orders.",15,MUTED),full(18));return;}for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)body.addView(orderCard(o,!dispatchedTab),full(12));}}
 private View orderCard(JSONObject o,boolean pending){LinearLayout card=col();card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(shape(SURFACE,14));TextView title=txt(o.optString("number","Order")+" • "+o.optString("buyer"),18,NAVY);title.setTypeface(Typeface.DEFAULT_BOLD);card.addView(title);card.addView(txt(o.optString("company")+(pending?" • Pending":" • Dispatched "+dateTime(o.optString("dispatchedAt"))),12,MUTED));JSONArray items=o.optJSONArray("items");if(items!=null){for(int j=0;j<items.length();j++){JSONObject x=items.optJSONObject(j);if(x==null)continue;String line=(j+1)+". "+x.optString("name")+" — Qty "+qty(x.optDouble("quantity"))+(x.optString("unit").isEmpty()?"":" "+x.optString("unit"));if(x.has("rate")&&!x.isNull("rate"))line+=" • "+currency.format(x.optDouble("rate"));card.addView(txt(line,14,NAVY),full(5));}}if(!o.optString("notes").isEmpty())card.addView(txt("Notes: "+o.optString("notes"),13,MUTED),full(8));if(pending){LinearLayout actions=new LinearLayout(this);actions.setPadding(0,dp(12),0,0);Button share=btn("Share details",v->shareOrder(o)),edit=btn("Edit",v->openForm(o)),dispatch=primary("Dispatched",v->dispatch(o));actions.addView(share,new LinearLayout.LayoutParams(0,-2,1));actions.addView(edit,new LinearLayout.LayoutParams(0,-2,1));actions.addView(dispatch,new LinearLayout.LayoutParams(0,-2,1));card.addView(actions);}else card.addView(txt("No share action • invoice is shared after dispatch",12,MUTED),full(10));return card;}
 private String qty(double v){if(Math.rint(v)==v)return String.valueOf((long)v);return String.valueOf(v);}
 private String dateTime(String v){try{return OffsetDateTime.parse(v).toLocalDateTime().format(DateTimeFormatter.ofPattern("dd-MM-yyyy hh:mm a"));}catch(Exception e){try{return Instant.parse(v).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("dd-MM-yyyy hh:mm a"));}catch(Exception ignored){return "";}}}
 private void shareOrder(JSONObject o){String text=o.optString("shareText");if(text.isEmpty()){toast("Only pending orders can be shared");return;}Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,"Share order details"));}
 private void dispatch(JSONObject o){new AlertDialog.Builder(this).setTitle("Mark dispatched?").setMessage(o.optString("number")+" • "+o.optString("buyer")+"\n\nIt will remain visible for 7 days, then be permanently removed. There is no share button after dispatch.").setNegativeButton("Cancel",null).setPositiveButton("Dispatched",(d,w)->{JSONObject q=new JSONObject();try{q.put("id",o.optString("id"));}catch(Exception ignored){}call("/api/v1/mobile/orders/dispatch","POST",q.toString(),x->{toast("Order marked dispatched");loadOrders();});}).show();}

 private void openForm(JSONObject order){editing=order;loadBootstrap(()->buildForm(order));}
 private void buildForm(JSONObject order){frame(order==null?"Add order":"Edit order","Buyer and item names come from Tally. Rate is optional.");itemRows.clear();buyerDetails=order==null?new JSONObject():order.optJSONObject("buyerDetails");if(buyerDetails==null)buyerDetails=new JSONObject();buyerDetailsFor=order==null?"":order.optString("buyer");List<String> names=companyNames();if(names.isEmpty()){body.addView(txt("No Tally company is available yet. Open a company in TallyPrime and sync first.",16,MUTED));return;}body.addView(txt("COMPANY",11,MUTED));Spinner companySpin=new Spinner(this);ArrayAdapter<String> ca=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);companySpin.setAdapter(ca);String wanted=order==null?store.get("company"):order.optString("company");int selected=Math.max(0,names.indexOf(wanted));companySpin.setSelection(selected);body.addView(companySpin,full(6));body.addView(txt("BUYER",11,MUTED),full(14));AutoCompleteTextView buyer=auto("Search buyer from Tally");if(order!=null)buyer.setText(order.optString("buyer"),false);body.addView(buyer,full(6));TextView buyerInfo=txt(buyerSummary(buyerDetails),12,MUTED);body.addView(buyerInfo);LinearLayout itemsBox=col();body.addView(txt("ITEMS",11,MUTED),full(16));body.addView(itemsBox);JSONArray existing=order==null?null:order.optJSONArray("items");Runnable rebuild=()->{itemsBox.removeAllViews();itemRows.clear();if(existing!=null&&existing.length()>0){for(int i=0;i<existing.length();i++)addItemRow(itemsBox,existing.optJSONObject(i));}else addItemRow(itemsBox,null);};rebuild.run();Button addItem=btn("+ Add another item",v->addItemRow(itemsBox,null));body.addView(addItem,full(8));body.addView(txt("NOTES",11,MUTED),full(16));EditText notes=input("Colours, packing, delivery instructions…",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);notes.setMinLines(2);if(order!=null)notes.setText(order.optString("notes"));body.addView(notes,full(6));Button save=primary(order==null?"Save pending order":"Update pending order",v->saveForm(order,companySpin,buyer,notes));body.addView(save,full(18));final String[] loadedCompany={""};companySpin.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){String c=names.get(pos);store.put("company",c);if(!c.equals(loadedCompany[0])){if(!loadedCompany[0].isEmpty()){buyer.setText("",false);buyerDetails=new JSONObject();buyerDetailsFor="";buyerInfo.setText(buyerSummary(buyerDetails));}loadedCompany[0]=c;buyer.setAdapter(null);loadMasters(c,buyer,buyerInfo);}}});buyer.setOnItemClickListener((p,v,pos,id)->fetchBuyer(companySpin.getSelectedItem().toString(),buyer.getText().toString(),buyerInfo));buyer.setOnFocusChangeListener((v,has)->{if(!has&&!buyer.getText().toString().trim().isEmpty())fetchBuyer(companySpin.getSelectedItem().toString(),buyer.getText().toString(),buyerInfo);});}
 private void loadMasters(String company,AutoCompleteTextView buyer,TextView buyerInfo){if(mastersLoading)return;mastersLoading=true;get(BridgeApi.path("orders/masters",company),x->{mastersLoading=false;parties=x.optJSONArray("parties");if(parties==null)parties=new JSONArray();JSONObject st=x.optJSONObject("stock");stock=st==null?new JSONArray():st.optJSONArray("items");if(stock==null)stock=new JSONArray();List<String> buyers=new ArrayList<>();for(int i=0;i<parties.length();i++){JSONObject p=parties.optJSONObject(i);if(p!=null&&!p.optString("name").isEmpty())buyers.add(p.optString("name"));}buyer.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_dropdown_item_1line,buyers));unitByItem.clear();for(int i=0;i<stock.length();i++){JSONObject s=stock.optJSONObject(i);if(s!=null)unitByItem.put(s.optString("name"),s.optString("unit"));}updateItemAdapters();if(!buyer.getText().toString().trim().isEmpty()&&buyerDetails.length()==0)fetchBuyer(company,buyer.getText().toString(),buyerInfo);});}
 private void fetchBuyer(String company,String buyer,TextView info){String selectedBuyer=buyer.trim();if(selectedBuyer.isEmpty())return;String path=BridgeApi.path("ledger-details",company,"ledger",selectedBuyer);get(path,x->{JSONObject d=x.optJSONObject("details");buyerDetails=d==null?new JSONObject():d;buyerDetailsFor=selectedBuyer;info.setText(buyerSummary(buyerDetails));});}
 private String buyerSummary(JSONObject d){if(d==null||d.length()==0)return "Select a buyer to fetch address / mobile / GST details.";String phone=first(d,"MOBILENUMBER","MOBILE","PHONENUMBER","PHONE"),address=first(d,"ADDRESS"),city=first(d,"CITY"),gst=first(d,"PARTYGSTIN","GSTIN");StringBuilder b=new StringBuilder();if(phone.length()>0)b.append("Mobile: ").append(phone);if(address.length()>0)b.append(b.length()>0?"\n":"").append(address);if(city.length()>0)b.append(address.length()>0?", ":(b.length()>0?"\n":"")).append(city);if(gst.length()>0)b.append(b.length()>0?"\n":"").append("GSTIN: ").append(gst);return b.length()==0?"Buyer selected. Tally returned no contact fields.":b.toString();}
 private String first(JSONObject d,String...keys){for(String k:keys){String v=d.optString(k).trim();if(!v.isEmpty())return v;}return "";}
 private void addItemRow(LinearLayout parent,JSONObject existing){LinearLayout box=col();box.setPadding(dp(12),dp(12),dp(12),dp(12));box.setBackground(shape(SURFACE,12));AutoCompleteTextView item=auto("Search Tally stock item");if(existing!=null)item.setText(existing.optString("name"),false);box.addView(item);TextView unit=txt(existing==null?"":existing.optString("unit"),12,MUTED);box.addView(unit);LinearLayout line=new LinearLayout(this);EditText qty=input("Qty",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL),rate=input("Rate (optional)",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);if(existing!=null){qty.setText(qty(existing.optDouble("quantity")));if(existing.has("rate")&&!existing.isNull("rate"))rate.setText(String.valueOf(existing.optDouble("rate")));}line.addView(qty,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,-2,1);rp.setMargins(dp(8),0,0,0);line.addView(rate,rp);box.addView(line,full(8));Button remove=btn("Remove item",v->{if(itemRows.size()<=1){toast("Keep at least one item");return;}ItemRow target=null;for(ItemRow r:itemRows)if(r.box==box)target=r;if(target!=null)itemRows.remove(target);parent.removeView(box);});box.addView(remove,full(6));parent.addView(box,full(8));ItemRow row=new ItemRow(box,item,qty,rate,unit);itemRows.add(row);setItemAdapter(row);item.setOnItemClickListener((p,v,pos,id)->{String name=item.getText().toString();unit.setText(unitByItem.getOrDefault(name,""));});item.setOnFocusChangeListener((v,has)->{if(!has)unit.setText(unitByItem.getOrDefault(item.getText().toString(),unit.getText().toString()));});}
 private void updateItemAdapters(){for(ItemRow r:itemRows)setItemAdapter(r);}
 private void setItemAdapter(ItemRow row){List<String> names=new ArrayList<>(unitByItem.keySet());Collections.sort(names,String.CASE_INSENSITIVE_ORDER);row.item.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_dropdown_item_1line,names));String u=unitByItem.get(row.item.getText().toString());if(u!=null&&!u.isEmpty())row.unit.setText(u);}
 private double number(String s)throws Exception{try{return Double.parseDouble(s.trim());}catch(Exception e){throw new Exception("Enter a valid quantity / rate");}}
 private void saveForm(JSONObject original,Spinner companySpin,AutoCompleteTextView buyer,EditText notes){try{String c=String.valueOf(companySpin.getSelectedItem()).trim(),b=buyer.getText().toString().trim();if(c.isEmpty()||b.isEmpty())throw new Exception("Select company and buyer");JSONArray items=new JSONArray();for(ItemRow r:itemRows){String name=r.item.getText().toString().trim(),q=r.qty.getText().toString().trim(),rate=r.rate.getText().toString().trim();if(name.isEmpty()||q.isEmpty())throw new Exception("Every item needs a product and quantity");JSONObject x=new JSONObject().put("name",name).put("quantity",number(q));String u=r.unit.getText().toString().trim();if(!u.isEmpty())x.put("unit",u);if(!rate.isEmpty())x.put("rate",number(rate));items.put(x);}JSONObject safeBuyerDetails=b.equalsIgnoreCase(buyerDetailsFor)?buyerDetails:new JSONObject();JSONObject payload=new JSONObject().put("company",c).put("buyer",b).put("buyerDetails",safeBuyerDetails).put("items",items).put("notes",notes.getText().toString().trim());if(original!=null)payload.put("id",original.optString("id"));call("/api/v1/mobile/orders","POST",payload.toString(),x->{store.put("company",c);OrdersWidget.refreshAll(this);toast(original==null?"Order saved":"Order updated");showOrders();});}catch(Exception e){toast(e.getMessage());}}
}
